<?php
require_once 'config.php';require_once 'functions.php';require_login();
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare("SELECT s.*,c.name customer_name,c.phone FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.id=?");$stmt->execute([$id]);$sale=$stmt->fetch();if(!$sale){http_response_code(404);exit('Invoice tidak ditemukan.');}
$stmt=$pdo->prepare("SELECT si.*,p.sku,p.name FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=?");$stmt->execute([$id]);$items=$stmt->fetchAll();$page_title='Detail Invoice';include 'header.php';?>
<section class="panel invoice"><div class="panel-head"><div><h2>MY STORE</h2><p class="muted">Bukti transaksi penjualan</p></div><button class="btn btn-light" onclick="window.print()">Cetak</button></div><p><b>Invoice:</b> <?=e($sale['invoice_no'])?><br><b>Tanggal:</b> <?=e($sale['sale_date'])?><br><b>Pelanggan:</b> <?=e($sale['customer_name']?:'Umum')?></p><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Jumlah</th><th>Harga</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['name'])?> (<?=e($it['sku'])?>)</td><td><?=$it['quantity']?></td><td><?=rupiah($it['price'])?></td><td><?=rupiah($it['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div><h2 class="invoice-total">Total: <?=rupiah($sale['total'])?></h2><a class="btn btn-light" href="sales.php">Kembali</a></section>
<?php include 'footer.php';?>
